}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Reference BiCG kernel. It computes:
#   s[j] = sum_i r[i] * A[i, j]
#   q[i] = sum_j A[i, j] * p[j]
# in a single pass over A laid out as A[n, m] in row-major order.
@proc
def kernel_bicg_unoptimized(
    m: size,
    n: size,
    A: DATA_TYPE[n, m] @ DRAM,
    s: DATA_TYPE[m] @ DRAM,
    q: DATA_TYPE[n] @ DRAM,
    p: DATA_TYPE[m] @ DRAM,
    r: DATA_TYPE[n] @ DRAM,
):
    # Zero-initialize s over its m entries
    for j in seq(0, m):
        s[j] = 0.0

    # Main BiCG computation: single pass over A
    for i in seq(0, n):
        q[i] = 0.0
        for j in seq(0, m):
            s[j] += r[i] * A[i, j]
            q[i] += A[i, j] * p[j]


# ---------------------------------------------------------------------------
# Scheduling: optimize kernel_bicg_unoptimized into a cache- and
# vector-friendly implementation while preserving semantics.
# ---------------------------------------------------------------------------

kernel_bicg_scheduled = kernel_bicg_unoptimized

# Tunable constants (compile-time) to adapt to a given CPU/cache.
# These can be adjusted without changing the C driver interface.
S_INIT_UNROLL = 4      # unroll factor for the s-initialization loop
J_BLOCK       = 64     # blocking factor for the inner j-loop (columns)
J_UNROLL      = 4      # unroll factor for the innermost j-loop

# 1) Optimize the s-initialization loop:
#    for j in 0..m: s[j] = 0
# Strip-mine and fully unroll a small inner loop to expose ILP and
# allow aggressive auto-vectorization of the memset-like pattern.
j_init = kernel_bicg_scheduled.find_loop("j")
kernel_bicg_scheduled = divide_loop(
    kernel_bicg_scheduled,
    j_init,
    S_INIT_UNROLL,
    ["j_init_outer", "j_init_inner"],
    tail="guard",
)
kernel_bicg_scheduled = unroll_loop(
    kernel_bicg_scheduled,
    kernel_bicg_scheduled.find_loop("j_init_inner"),
)

# 2) Tile the inner j-loop in the main BiCG computation:
#    This keeps a small stripe of s and p hot in cache while streaming
#    through a row of A, without changing the logical iteration order.
#    After step (1) there is no remaining loop with iterator 'j' in
#    the initialization, so this 'j' refers to the main loop.
j_main = kernel_bicg_scheduled.find_loop("j")
kernel_bicg_scheduled = divide_loop(
    kernel_bicg_scheduled,
    j_main,
    J_BLOCK,
    ["j_block", "j_block_inner"],
    tail="guard",
)

# 3) Further strip-mine j_block_inner and unroll the innermost loop.
#    This creates a fixed-size inner loop (length J_UNROLL) that maps
#    well to SIMD registers and maximizes instruction-level parallelism.
j_block_inner = kernel_bicg_scheduled.find_loop("j_block_inner")
kernel_bicg_scheduled = divide_loop(
    kernel_bicg_scheduled,
    j_block_inner,
    J_UNROLL,
    ["j_vec_block", "j_vec"],
    tail="guard",
)
kernel_bicg_scheduled = unroll_loop(
    kernel_bicg_scheduled,
    kernel_bicg_scheduled.find_loop("j_vec"),
)

# 4) Simplify algebraically equivalent control/expressions generated
#    during tiling and unrolling.
kernel_bicg_scheduled = simplify(kernel_bicg_scheduled)

# 5) Expose the final optimized kernel under the name expected by the
#    C driver and header: kernel_bicg.
kernel_bicg = rename(kernel_bicg_scheduled, "kernel_bicg")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, M, n, m);
  POLYBENCH_1D_ARRAY_DECL(s, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(q, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(p, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (m, n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(r),
	      POLYBENCH_ARRAY(p));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_bicg(/*ctxt=*/NULL, m, n,
	      (DATA_TYPE*)POLYBENCH_ARRAY(A),
	      (DATA_TYPE*)POLYBENCH_ARRAY(s),
	      (DATA_TYPE*)POLYBENCH_ARRAY(q),
	      (DATA_TYPE*)POLYBENCH_ARRAY(p),
	      (DATA_TYPE*)POLYBENCH_ARRAY(r));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(s), POLYBENCH_ARRAY(q)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(s);
  POLYBENCH_FREE_ARRAY(q);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(r);

  return 0;
