#    and then fully unroll the fixed-size inner ji-loop. The tail loop
#    handles any remainder when m is not divisible by VEC_WIDTH.
kernel_bicg_opt = divide_loop(kernel_bicg_opt, "j #1", VEC_WIDTH, ("jo", "ji"), tail="cut")
kernel_bicg_opt = unroll_loop(kernel_bicg_opt, kernel_bicg_opt.find_loop("ji"))

